static input_event ev(int type,int code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
static void stroke(Shell& s,Canvas& c,bool eraser,int x,int y,int ex){auto engine=std::make_unique<spike::Engine>(spike::Transform{{0,1619},{0,2159},1620,2160,0,false},s.ink(),c);spike::FrameAssembler a;spike::Scheduler scheduler;spike::SessionStats stats;
 std::array down={ev(EV_KEY,BTN_TOOL_PEN,!eraser),ev(EV_KEY,BTN_TOOL_RUBBER,eraser),ev(EV_ABS,ABS_X,x),ev(EV_ABS,ABS_Y,y),ev(EV_KEY,BTN_TOUCH,1),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(down,a,*engine,scheduler,stats,1,nullptr,&s));
 CHECK(!s.action(Action::Exit,true));CHECK(!s.action(Action::Next,true));CHECK(!s.action(Action::Hide,true));CHECK(!s.action(Action::Hide));CHECK(s.document()->contact());
 std::array move={ev(EV_ABS,ABS_X,ex),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(move,a,*engine,scheduler,stats,8000001,nullptr,&s));std::array up={ev(EV_KEY,BTN_TOUCH,0),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(up,a,*engine,scheduler,stats,16000001,nullptr,&s));CHECK(stats.samples==3&&stats.contacts==1&&stats.released==1&&!s.document()->contact());}
