 test("show_hide_repeat_bounded_regions_no_full_page_damage",[&]{auto clean=c.pixels;for(int n=0;n<3;++n){auto submissions=c.submissions,full=c.full;auto area=c.area;CHECK(hit(s.state(),800,2100)==Action::Show);CHECK(s.action(Action::Show));c.changes();std::uint64_t regional=0;unsigned count=0;const auto R=regions();for(unsigned r=0;r<R.size();++r)if(ChromeRegions&(1u<<r)){regional+=std::uint64_t(R[r].x1-R[r].x0)*(R[r].y1-R[r].y0);++count;}CHECK(c.submissions-submissions==count&&c.full==full&&c.area-area==regional);for(int y=0;y<2160;++y)for(int x=0;x<1620;++x)if(!R[0].contains(x,y)&&!R[1].contains(x,y)&&!R[2].contains(x,y))CHECK(c.pixels[y*1632+x]==clean[y*1632+x]);if(!n)preview(data/"chrome-page0.pgm",c.pixels);CHECK(s.action(Action::Hide));c.changes();CHECK(c.pixels==clean&&s.document()->active().prepared.binding==binding);}});
